package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl *template.Template

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	tmpl = template.Must(template.New("report").Parse(reportTemplate))
}

const reportTemplate = `<html><body>
<h1>Employee Directory</h1>
<table>{{range .Rows}}<tr><td>{{.Name}}</td><td>{{.Department}}</td><td>{{.Salary}}</td></tr>{{end}}</table>
</body></html>`

type Row struct {
	Name       string
	Department string
	Salary     string
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	dept := r.URL.Query().Get("dept")
	sortCol := r.URL.Query().Get("sort")

	// Validate sort column against allowlist
	allowedSorts := map[string]bool{"name": true, "department": true, "hire_date": true}
	if sortCol == "" {
		sortCol = "name"
	}
	if !allowedSorts[sortCol] {
		http.Error(w, "Invalid sort column", 400)
		return
	}

	// Sanitize department - remove obvious dangerous chars
	dept = strings.ReplaceAll(dept, ";", "")
	dept = strings.ReplaceAll(dept, "/*", "")
	dept = strings.ReplaceAll(dept, "*/", "")

	// Build query with parameterized sort (safe) but inline dept filter
	query := fmt.Sprintf(
		"SELECT name, department, salary FROM employees WHERE department ILIKE '%%%s%%' ORDER BY %s",
		dept, sortCol,
	)

	log.Printf("[AUDIT] search query executed by %s: dept=%s sort=%s", r.RemoteAddr, dept, sortCol)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("[ERROR] query failed: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []Row
	for rows.Next() {
		var row Row
		if err := rows.Scan(&row.Name, &row.Department, &row.Salary); err != nil {
			continue
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, struct{ Rows []Row }{results})
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
